@Test @MainActor
func historyMetaExclusionSurvivesTranscriptRestore() async throws {
    // isMetaだけの履歴：discoveryは候補を空にし、既存loaderは本文をuserMessageとして返す。
    let entry = ClaudeSessionHistoryEntry(sessionID: "history-meta", preview: "内部補足", firstUserAt: nil, lastModified: Date(), gitBranch: nil, fileURL: URL(fileURLWithPath: "/tmp/history-meta.jsonl"), titleUserMessages: [])
    let (vm, _) = makeChatVM(historyTranscriptLoader: { _ in
        [.userMessage(id: "meta", text: "内部補足", timestamp: Date())]
    })
    await vm.startFromHistory(entry)
    #expect(vm.titleState.source == .flower)
    // ターン境界保存の対象と同じtranscriptを、既存の復元テスト方式で再投入する。
    let store = TitleLifecycleTranscriptStore(vm.transcript)
    let (restored, _) = makeChatVM(transcriptStore: store)
    await restored.restore(threadId: "history-meta", approvalPolicy: .named("on-request"), sandbox: .named("workspace-write"))
    #expect(restored.restoreState == .restored)
    #expect(restored.titleState.source == .flower)
    #expect(restored.titleState.name == "Rose")
    await vm.terminate()
    await restored.terminate()
}
